// Keep the investigation and reference material visible together.
let sideTab='notebook',practice=null,profilePerson=null,profileListPage=0;
const sideItems=[['notebook','捜査手帳'],['people','人物資料'],['history','会話履歴'],['final','最終推理']];
const baseBoard=board,baseDialogue=renderDialogue,baseNotebook=notebook,baseProfiles=profiles,baseHistory=history,baseFinal=finalPanel,baseStart=start;
function sideTarget(fn){const main=document.querySelector('#panel'),side=document.querySelector('#reference-panel');if(!side)return fn();if(main)main.id='investigation-panel';side.id='panel';try{return fn();}finally{side.id='reference-panel';if(main)main.id='panel';}}
notebook=()=>sideTarget(baseNotebook);profiles=()=>sideTarget(baseProfiles);history=()=>sideTarget(baseHistory);finalPanel=()=>sideTarget(baseFinal);
function reference(){const el=$('#reference-panel');if(!el)return;if(practice&&practice.step===4){practiceNotebook();return;}({notebook,people:profiles,history,final:finalPanel}[sideTab]||notebook)();}
function workspace(){if($('#workspace'))return;const app=$('#app'),left=document.createElement('div');left.id='play-column';while(app.firstChild)left.append(app.firstChild);app.innerHTML=`<div id="workspace"><aside id="reference"><nav class="reference-tabs" aria-label="右メニュー">${sideItems.map(([id,label])=>`<button data-reference="${id}" class="${sideTab===id?'active':''}">${label}</button>`).join('')}</nav><section id="reference-panel" tabindex="0" aria-label="資料の内容"></section><div class="reference-controls"><button id="reference-up" aria-label="資料の前のページ">↑ 前へ</button><button id="reference-down" aria-label="資料の次のページ">次へ ↓</button></div></aside></div>`;$('#workspace').prepend(left);document.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>{sideTab=b.dataset.reference;if(sideTab==='people'){profilePerson=null;profileListPage=0;}document.querySelectorAll('[data-reference]').forEach(x=>x.classList.toggle('active',x===b));reference();});$('#reference-up').onclick=()=>$('#reference-panel').scrollBy({top:-$('#reference-panel').clientHeight*.8,behavior:reducedMotion?'instant':'smooth'});$('#reference-down').onclick=()=>$('#reference-panel').scrollBy({top:$('#reference-panel').clientHeight*.8,behavior:reducedMotion?'instant':'smooth'});reference();if(practice)practiceGuide();}
board=function(){if(practice){practiceBoard();return;}tab='investigate';baseBoard();const tabs=$('#app .tabs');if(tabs)tabs.remove();workspace();};
renderDialogue=function(){baseDialogue();workspace();};
// Reference actions never discard the live conversation when selecting a viewpoint.
profiles=function(){
const panel=$('#reference-panel')||$('#panel');
if(profilePerson===null){
  panel.dataset.folioStart=String(profileListPage);
  panel.innerHTML=`<h3>人物資料</h3><p>アイコンを選ぶと詳しい人物資料を読めます。</p><div class="character-directory">${Array.from({length:8},(_,row)=>`<div class="character-icon-row">${HISUI.people.slice(row*2,row*2+2).map(p=>`<button class="character-icon" data-profile="${p.id}" aria-label="${p.name}の人物資料">${portrait(p.id,0,'directory-portrait')}<strong>${p.name}</strong></button>`).join('')}</div>`).join('')}</div><h3>館で働く人たち</h3><p>管理人、庭師、パティシエ。勤務や納品の記録で動きを確かめられます。</p>`;
  panel.querySelectorAll('[data-profile]').forEach(button=>button.onclick=()=>{profileListPage=Number(panel.dataset.folioPage||0);profilePerson=Number(button.dataset.profile);profiles();});
  return;
}
const p=HISUI.people[profilePerson];
panel.dataset.folioStart='0';
panel.innerHTML=`<button id="profile-list" class="profile-back">← アイコン一覧</button><article class="character-detail">${portrait(p.id,0,'detail-portrait')}<h3>${p.name}</h3><p class="quote">「${esc(p.voice)}」</p><h3>得意な視点</h3><p>${esc(p.skill)}</p><h3>人物の様子</h3><p>${esc(p.weak)}</p><button data-viewpoint="${p.id}" class="primary">この人を聞き手にする</button></article>`;
$('#profile-list').onclick=()=>{profilePerson=null;profiles();};
panel.querySelector('[data-viewpoint]').onclick=()=>{selection.a=p.id;if(selection.a===selection.b)selection.b=(selection.a+1)%16;if(view!=='reading')board();else toast('次の対話の聞き手を変更しました。現在の会話はそのまま読めます。');};
};
const legacyHistory=history;history=function(){legacyHistory();document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const e=state.history.find(h=>h.turn===Number(b.dataset.history));modal(`<h2>${HISUI.people[e.a].name}と${HISUI.people[e.b].name}</h2>${e.lines.map(l=>`<div class="utterance"><span>${esc(l.speaker)}</span><p>${esc(l.text)}</p></div>`).join('')}`);});};
function practiceGuide(){const notes=[['聞き手を選ぶ','「操作する人物を変更」を開き、好きな人物を選びましょう。毎ターン視点を変えられます。'],['話し相手を選ぶ','「会話する人物を変更」を開き、別の人物を選びましょう。'],['言葉を選ぶ','話題と具体的なセリフを選んで「練習の対話」を押しましょう。強い追及はすれ違いを招きます。'],['会話を読む','「次の言葉」で読み進めます。右の手帳も同時に確認できます。'],['記録を照合する','右の練習用記録を2つ選んで照合しましょう。証拠の共通点から結論を作ります。'],['捜査を始める','本編では相性を会話から発見します。噂は証拠で訂正でき、信頼も回復できます。30回の対話で集めたキーワードを最終推理へつなぎましょう。']];const [title,text]=notes[practice.step];const box=document.createElement('section');box.className='practice-guide';box.innerHTML=`<strong>操作練習 ${practice.step+1} / 6 · ターン消費なし — ${title}</strong><p>${text}</p>${practice.step===5?'<button id="practice-finish" class="primary">本編を始める（残り30回）</button>':''}<button id="practice-skip" class="quiet">練習を終えて本編へ</button>`;$('#play-column').prepend(box);$('#practice-skip').onclick=finishPractice;if($('#practice-finish'))$('#practice-finish').onclick=finishPractice;}
function beginPractice(){practice={step:0};view='board';board();}
function finishPractice(){practice=null;state.tutorialDone=true;save();selection.proof='';sideTab='notebook';view='board';board();}
function practiceBoard(){tab='investigate';baseBoard();$('#app .tabs')?.remove();$('#panel .notice')?.remove();$('#talk').innerHTML='練習の対話 →';workspace();for(const which of ['a','b']){const button=document.querySelector(`[data-picker="${which}"]`);button.onclick=()=>{openPersonPicker(which);document.querySelectorAll(`[data-${which}]`).forEach(el=>el.onclick=()=>{selection[which]=Number(el.dataset[which]);if(selection.a===selection.b)selection.b=(selection.a+1)%16;$('#modal').close();practice.step=Math.max(practice.step,which==='a'?1:2);board();});};}
// Refreshing topic/approach must preserve the surrounding two-column layout.
document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>{selection.topic=el.dataset.topic;board();});document.querySelectorAll('[data-approach]').forEach(el=>el.onclick=()=>{selection.approach=el.dataset.approach;board();});$('#talk').onclick=()=>{if(practice.step<2){toast('先に聞き手と話し相手を選んでみましょう。');return;}practice.step=3;shown={turn:0,a:selection.a,b:selection.b,topic:selection.topic,outcome:'操作練習',gained:[],keys:[],lines:[{speaker:HISUI.people[selection.a].name,text:Game.dialogueChoices(selection.topic).find(v=>v[0]===selection.approach)[1]},{speaker:HISUI.people[selection.b].name,text:selection.approach==='challenge'?'強く疑われると話しにくいね。記録を一緒に確認する言い方も試してみよう。':'記録を一緒に見よう。これは操作練習だから、事件の証拠や信頼は変わらないよ。'},{speaker:'地の文',text:'右の手帳で、観察と記録を照合してみよう。重要キーワードは会話だけでは増えない。'}]};view='reading';render();};}
const practiceBaseDialogue=renderDialogue;renderDialogue=function(){practiceBaseDialogue();if(practice&&$('#dialogue-done'))$('#dialogue-done').onclick=()=>{practice.step=4;sideTab='notebook';view='board';board();};};
function practiceNotebook(){$('#reference-panel').innerHTML=`<h3>練習用の記録</h3><p>事件とは無関係の練習です。</p><article class="list-entry"><h3>カップの観察</h3><p>底面に「翡翠荘」の刻印がある。</p></article><article class="list-entry"><h3>備品台帳</h3><p>館のカップには「翡翠荘」の刻印がある。</p></article>${[0,1].map(i=>`<label class="field">記録 ${i+1}<select id="practice-proof-${i}"><option value="">選んでください</option><option value="cup">カップの観察</option><option value="inventory">備品台帳</option></select></label>`).join('')}<button id="practice-compare" class="primary">練習の照合</button><p id="practice-feedback" role="status"></p>`;$('#practice-compare').onclick=()=>{if($('#practice-proof-0').value&&$('#practice-proof-1').value&&$('#practice-proof-0').value!==$('#practice-proof-1').value){practice.step=5;board();$('#reference-panel').innerHTML='<h3>照合成立</h3><p>刻印と台帳が一致し、「館の備品」という結論が裏付けられました。本編でも、証拠の共通点を探しましょう。</p>';}else $('#practice-feedback').textContent='異なる2つの記録を選んでください。失敗してもターンや信頼は減りません。';};}
start=function(){practice=null;baseStart();};
const baseIntro=intro;intro=function(){baseIntro();const next=$('#intro-next'),handler=next.onclick;next.onclick=()=>{if(openingPage===HISUI.opening.length-1&&!state.tutorialDone)beginPractice();else handler();};};
const resumeRender=render;render=function(){resumeRender();if(view==='board'&&!state.tutorialDone&&!practice&&!state.ended&&state.turn===0)beginPractice();};
// Japanese word boundaries: keep words and their closing punctuation together.
const segmenter=new Intl.Segmenter('ja',{granularity:'word'});
function words(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode()){const n=walker.currentNode;if(!n.textContent.trim()||n.parentElement.closest('script,style,textarea,select,option,[data-word],svg'))continue;nodes.push(n);}for(const n of nodes){const parts=[];let opening='';for(const {segment,isWordLike} of segmenter.segment(n.textContent)){if(/^[「『（【]$/.test(segment)){opening+=segment;continue;}if(!isWordLike&&parts.length&&!/\s/.test(segment)){parts[parts.length-1]+=segment;continue;}parts.push(opening+segment);opening='';}if(opening)parts.push(opening);const frag=document.createDocumentFragment();for(const part of parts){if(/^\s+$/.test(part)){frag.append(document.createTextNode(part));continue;}const span=document.createElement('span');span.dataset.word='';span.textContent=part;frag.append(span);frag.append(document.createElement('wbr'));}n.replaceWith(frag);}}
let wordPending=false;const observer=new MutationObserver(()=>{if(wordPending)return;wordPending=true;queueMicrotask(()=>{observer.disconnect();words(document.body);observer.observe(document.body,{subtree:true,childList:true,characterData:true});wordPending=false;});});observer.observe(document.body,{subtree:true,childList:true,characterData:true});
render();words(document.body);
